    <style>
      :root {
        color-scheme: dark;
        --background: #0b1020;
        --panel: #121a2e;
        --panel-border: #263454;
        --text: #f4f7fb;
        --muted: #aeb9cc;
        --accent: #7dd3fc;
        --accent-strong: #38bdf8;
        --error: #fca5a5;
        --shadow: rgba(0, 0, 0, 0.4);
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        display: grid;
        place-items: center;
        padding: 32px 16px;
        background:
          radial-gradient(circle at top left, rgba(56, 189, 248, 0.18), transparent 34rem),
          linear-gradient(135deg, #080c18 0%, var(--background) 48%, #111827 100%);
        color: var(--text);
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        line-height: 1.5;
      }

      .support-card {
        width: min(100%, 560px);
        padding: clamp(24px, 5vw, 40px);
        border: 1px solid var(--panel-border);
        border-radius: 28px;
        background: rgba(18, 26, 46, 0.92);
        box-shadow: 0 24px 70px var(--shadow);
        backdrop-filter: blur(16px);
      }

      .eyebrow {
        margin: 0 0 10px;
        color: var(--accent);
        font-size: 0.82rem;
        font-weight: 700;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 5vw, 3rem);
        line-height: 1.05;
      }

      .intro {
        margin: 16px 0 28px;
        color: var(--muted);
      }

      .form-field {
        margin-bottom: 20px;
      }

      label {
        display: block;
        margin-bottom: 8px;
        font-weight: 700;
      }

      input {
        width: 100%;
        min-height: 52px;
        padding: 14px 16px;
        border: 1px solid #3c4a66;
        border-radius: 16px;
        background: #0b1223;
        color: var(--text);
        font: inherit;
        transition:
          border-color 160ms ease,
          box-shadow 160ms ease,
          background 160ms ease;
      }

      input::placeholder {
        color: #71809a;
        opacity: 1;
      }

      input:focus {
        border-color: var(--accent-strong);
        background: #0d1629;
        box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.18);
        outline: none;
      }

      .helper-text {
        margin: 8px 0 0;
        color: var(--muted);
        font-size: 0.92rem;
      }

      .error-message {
        margin: 8px 0 0;
        color: var(--error);
        font-size: 0.92rem;
      }

      .is-invalid input {
        border-color: var(--error);
      }

      button {
        width: 100%;
        min-height: 54px;
        margin-top: 4px;
        border: 0;
        border-radius: 16px;
        background: linear-gradient(135deg, var(--accent), var(--accent-strong));
        color: #06111f;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        box-shadow: 0 16px 34px rgba(56, 189, 248, 0.2);
      }

      button:hover {
        filter: brightness(1.06);
      }

      button:focus-visible {
        outline: 4px solid rgba(125, 211, 252, 0.42);
        outline-offset: 4px;
      }

